def wrap_and_count(text, width):
    words = text.split()
    if not words:
        return 0
    def pack(remaining, line_len):
        if not remaining:
            return 1
        word = remaining[0]
        needed = len(word) if line_len == 0 else line_len + 1 + len(word)
        if needed <= width:
            return pack(remaining[1:], needed)
        return 1 + pack(remaining[1:], len(word))
    return pack(words, 0)

