def plateau_count(lst):
    n = len(lst)
    count = 0
    run_len = 1
    for i in range(1, n + 1):
        if i < n and lst[i] == lst[i - 1]:
            run_len += 1
        else:
            if run_len >= 2:
                count += 1
            run_len = 1
    return count

