def count_happy_numbers_in_range(a, b):
    def digit_square_sum(x):
        total = 0
        while x:
            x, d = divmod(x, 10)
            total += d * d
        return total

    def is_happy(x):
        seen = set()
        while x != 1 and x not in seen:
            seen.add(x)
            x = digit_square_sum(x)
        return x == 1

    return sum(1 for x in range(a, b + 1) if is_happy(x))

